const unitById=(id)=>UNITS.find(x=>x.id===id);
const make=(tag,cls,content)=>{const el=document.createElement(tag);if(cls)el.className=cls.split(/\s+/).filter(Boolean).map(x=>'s421'+x).join(' ');if(content!==undefined)el.textContent=String(content);return el};
const b=(label,action,cls='')=>{const el=make('button','btn '+cls,label);el.type='button';el.addEventListener('click',action);return el};
const card=(cls='')=>make('section','card '+cls);
let session=null,voiceCount=0,viewGroup=0;
const labels=['練習','単元テスト','まちがい直し'];
function stopVoice(){try{window.speechSynthesis?.cancel()}catch(_){}}
function readAloud(text,slow=false,lang='ja-JP'){try{if(!window.speechSynthesis||!window.SpeechSynthesisUtterance)throw new Error('unsupported');stopVoice();const utt=new SpeechSynthesisUtterance(String(text));utt.lang=lang;utt.rate=slow?.68:.94;window.speechSynthesis.speak(utt);voiceCount++}catch(_){alert('この端末では音声を再生できません。画面の文字で学習できます。')}}
function voice(text,lang='ja-JP'){const bar=make('div','audio');bar.append(b('🔊 よみあげ',()=>readAloud(text,false,lang)),b('🐢 ゆっくり',()=>readAloud(text,true,lang)));return bar}
function screen(title,goBack){stopVoice();root.replaceChildren();const page=make('section','page'),head=make('header','head');head.append(b('← もどる',goBack||home,'back'),make('h1','',title));page.append(head);root.append(page);try{window.scrollTo({top:0,behavior:'instant'})}catch(_){window.scrollTo(0,0)}return page}
function oldEnglish(){if(typeof subjectGradeTerms==='function')return subjectGradeTerms('英語',4);if(typeof window.ponoAllGrades390==='function')return window.ponoAllGrades390(4);if(typeof child==='function')return child();return home()}
function detail(id){const u=unitById(id);return u?overview(id):home()}
function trail(u){return GROUPS[u.group].icon+' '+GROUPS[u.group].name+' ／ '+u.title}
function home(){session=null;voiceCount=0;const page=screen('🌍 小学4年 英語｜18小単元',oldEnglish),intro=card('intro');intro.append(make('h2','','9つの大単元から小単元を選ぼう'),make('p','','授業を受けていなくても、一つずつ「まなぶ → いっしょに話す → 練習 → 単元テスト」と進めます。聞く・話すことが中心。音声は何回聞いても減点しません。文字はヒントとして使います。発音の自動採点はしません。'));page.append(intro);
GROUPS.forEach((g,i)=>{const c=card('group'),h=make('h2','',g.icon+' '+(i+1)+'．'+g.name);c.append(h,make('p','small',g.desc),b(viewGroup===i?'小単元を表示中':'この大単元の小単元を見る',()=>{viewGroup=i;home()},'wide '+(viewGroup===i?'primary':'')));if(viewGroup===i){const wrap=make('div','sublist');UNITS.filter(u=>u.group===i).forEach((u,k)=>{const line=make('div','subitem');line.append(make('strong','',`${i+1}-${k+1} ${u.icon} ${u.title}`),make('p','small',u.goal),b('この小単元を学ぶ →',()=>overview(u.id),'primary wide'));wrap.append(line)});c.append(wrap)}page.append(c)});
page.append(b('← これまでの英語の単元一覧へ',oldEnglish,'wide'));}
function overview(id){const u=unitById(id);if(!u)return home();viewGroup=u.group;const page=screen(u.icon+' '+u.title,home),c=card('intro');c.append(make('p','small',trail(u)),make('h2','','聞いて、まねして、使ってみよう'),make('p','',u.goal),make('p','small','ひとつずつ進んでも、テストから始めても大丈夫。自分のペースで進めましょう。'));page.append(c);
page.append(b('📖 ① まなぶ・音を聞く（3ページ）',()=>learn(id,0),'primary wide'),b('🤝 ② いっしょに話す',()=>together(id,false),'wide'),b('🌱 ③ 練習6問',()=>start(id,'practice'),'wide'),b('📝 ④ 単元テスト10問',()=>start(id,'test'),'wide'));page.append(make('p','small','練習は1問ずつ解説。テストは最後にまとめて答え合わせできます。'));}
function diagram(u,index){const d=make('div','visual'),title=make('p','diagramtitle','🔊 音を聞いてまねしてみよう');d.append(title);
 const n=Math.ceil(u.examples.length/3),m=Math.ceil((u.examples.length-n)/2);const pairs=index===0?u.examples.slice(0,n):index===1?u.examples.slice(n,n+m):u.examples.slice(n+m);
 pairs.forEach(([en,jp])=>{const line=make('div','wordline');line.append(b('🔊 '+en,()=>readAloud(en,false,'en-US'),'word'),make('span','',jp));d.append(line)});return d}
function learn(id,index){const u=unitById(id);if(!u)return home();const l=u.lessons[index],page=screen(`${u.icon} ${u.title}｜まなぶ ${index+1}/3`,()=>index?learn(id,index-1):overview(id));const c=card('lesson');c.append(make('p','small',`まなぶ ${index+1}/3`),make('h2','',l[0]),make('p','',l[1]),diagram(u,index),make('p','tip','💡 '+l[3]));page.append(c,voice(l[1]+'。'+l[3]));if(index<2)page.append(b('つぎの説明へ →',()=>learn(id,index+1),'primary wide'));else page.append(b('いっしょに話す →',()=>together(id,false),'primary wide'),b('練習6問へ進む',()=>start(id,'practice'),'wide'));}
function together(id,reveal){const u=unitById(id);if(!u)return home();const [q,a,ex]=u.together,page=screen('🤝 いっしょに話す｜'+u.title,()=>learn(id,2)),c=card('together');c.append(make('h2','','まず自分で考えてみよう'),make('p','prompt',q),make('p','small','英語を聞いて、まねしてみよう。声に出せなくても大丈夫。'));if(reveal)c.append(make('div','answer','答え：'+a),make('p','',ex));else c.append(b('答えと考え方を見る',()=>together(id,true),'primary wide'));page.append(c,voice(q));page.append(b('練習6問へ進む →',()=>start(id,'practice'),'wide'))}
function start(id,mode,retry){const u=unitById(id);if(!u)return home();if(!['practice','test','retry'].includes(mode))return home();const items=mode==='retry'?retry:mode==='practice'?u.practice:u.test;if(!items?.length)return overview(id);session={id,mode,items:items.map(q=>({...q})),i:0,picks:[],start:Date.now(),saved:false};voiceCount=0;question()}
function options(q,i){const arr=[q.a,q.b,q.c];const code=UNITS.findIndex(u=>u.id===session.id);const shift=(code+i*2+Math.floor(i/2))%3;return [arr[shift],arr[(shift+1)%3],arr[(shift+2)%3]]}
function question(){if(!session)return home();const s=session,q=s.items[s.i];if(!q)return result();const u=unitById(s.id),kind=s.mode==='practice'?labels[0]:s.mode==='test'?labels[1]:labels[2],page=screen(`${kind}｜${u.title}`,()=>overview(s.id));page.append(make('p','progress',`${s.i+1} / ${s.items.length} 問`));const c=card('question');c.append(make('h2','',q.q));const choices=options(q,s.i);choices.forEach(x=>c.append(b(x,()=>answer(x),'choice')));if(q.audio){c.append(voice(q.audio,'en-US'));if(q.hidden){const reveal=make('p','small','聞こえにくいときは文字を確かめられます。');c.append(reveal,b('英語の文字を見る',()=>{reveal.textContent='英語：'+q.audio},'wide'));}}const optionsEnglish=choices.some(x=>/[A-Za-z]/.test(x));if(optionsEnglish)c.append(make('p','small','選択肢を選んでください。英語の表現は音を聞いて確認できます。'));page.append(c,make('p','small',s.mode==='test'?'最後にまとめて採点します。':'答えたら解説を確認できます。'));}
function answer(choice){const s=session;if(!s||s.picks.length!==s.i)return;s.picks.push(choice);if(s.mode==='test'){s.i++;question()}else feedback()}
function feedback(){const s=session;if(!s)return home();const u=unitById(s.id),q=s.items[s.i],correct=s.picks[s.i]===q.a,page=screen(`考え方｜${u.title}`,()=>overview(s.id)),c=card('feedback');c.append(make('h2','',correct?'○ せいかい！':'いっしょに確かめよう'),make('p','','あなたの答え：'+s.picks[s.i]),make('p','','答え：'+q.a),make('p','',q.ex));page.append(c,voice(q.ex),b('つぎの問題へ →',()=>{s.i++;question()},'primary wide'));}
function saveRecord(){const s=session;if(!s)return false;if(s.saved)return true;const u=unitById(s.id),score=s.items.filter((q,i)=>s.picks[i]===q.a).length,rate=Math.round(score*100/s.items.length);try{if(typeof profile==='undefined'||!profile?.id||typeof records==='undefined'||!Array.isArray(records)||typeof save!=='function')return false;
 const label=s.mode==='test'?'単元テスト':s.mode==='retry'?'まちがい復習':'練習';const rec={studentId:profile.id,date:new Date().toISOString(),subject:'英語',grade:4,unit:u.title,unitId:'english421_'+u.id,content:`小学4年 英語 ${GROUPS[u.group].name}／${u.title} ${label}${s.items.length}問`,correct:score,total:s.items.length,rate,score:rate,reads:voiceCount,seconds:Math.max(0,Math.round((Date.now()-s.start)/1000)),status:label,supportNote:'英語の音声は何度聞いても減点なし。発音や会話力を自動採点していません。'};records.push(rec);try{save();s.saved=true;return true}catch(_){records.pop();return false}
 }catch(_){return false}}
